import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { Product } from '../../src/entities/product.entity';
import { buildProduct } from '../factories/product.factory';
import { Category } from '../../src/entities/category.entity';
import { buildCategory } from '../factories/category.factory';
import { ProductStatus } from '../../src/enums/product-status.enum';

describe('Product Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let categoryId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const categoryEntity = em.create(
      Category,
      buildCategory(),
    );
    await em.persistAndFlush(categoryEntity);
    categoryId = categoryEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    const entity = em.create(Product, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    const saved = em.create(Product, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(Product, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(Product, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    const saved = em.create(Product, data);
    await em.persistAndFlush(saved);
    saved.slug = `updated-${Date.now()}`;
    await em.flush();
    const reloaded = await em.findOne(Product, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.slug).toEqual(saved.slug);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    const saved = em.create(Product, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(Product, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    await em.persistAndFlush(em.create(Product, data));
    const all = await em.find(Product, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('finds entity by unique field slug', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId, slug: `test-${Date.now()}` });
    const saved = em.create(Product, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(Product, {
      slug: `test-${Date.now()}`,
    });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('persists with category foreign key', async () => {
    const em = orm.em.fork();
    const data = buildProduct({ category: categoryId });
    const saved = em.create(Product, data);
    await em.persistAndFlush(saved);
    await em.populate(saved, ['category']);
    expect(saved.category.id).toBe(categoryId);
  });
});
